#include "../mage_prefill_m89d_t32_microtile/mage_prefill_m89d_t32_microtile.hpp"
#include <hls_half.h>
#include <hls_math.h>
#include <iostream>
#include <random>
void m89s_scaleaware(hls::stream<m89_axis128_t>&,const ap_uint<128>*,const ap_uint<128>*,const ap_uint<128>*,const ap_uint<128>*,hls::stream<m89_axis64_t>&,unsigned,unsigned,unsigned,ap_uint<32>&,ap_uint<32>&,ap_uint<32>&,ap_uint<32>&);
static ap_uint<16> hb(half v){fp_struct<half>x(v);return x.data();}static half bh(ap_uint<16>b){fp_struct<half>x(b);return x.to_half();}
static void put(ap_uint<128>&lo,ap_uint<128>&hi,unsigned l,unsigned b,unsigned v){if(b==2)lo.range(2*l+1,2*l)=v;else if(l<32)lo.range(4*l+3,4*l)=v;else hi.range(4*(l-32)+3,4*(l-32))=v;}
static int qm(unsigned b,bool o){int h=1<<(b-1);return o?-h+1:-h;}
static int run(unsigned bits){const unsigned G=3,R=8,S=4,W=1+4*bits;static ap_uint<128>m[S][G*17];static int a[G][32][64];half as[G][32],gold[32][S][8];hls::stream<m89_axis128_t>tx;hls::stream<m89_axis64_t>rx;std::mt19937 gen(0x4d383953+bits);std::uniform_int_distribution<int>ad(-31,31),cd(0,(1<<bits)-1),bd(0,1);for(unsigned t=0;t<32;++t)for(unsigned s=0;s<S;++s)for(unsigned r=0;r<8;++r)gold[t][s][r]=(half)0;
 for(unsigned g=0;g<G;++g)for(unsigned t=0;t<32;++t){as[g][t]=(half)(0.002f*(g+1)*(1+(t%7)));for(unsigned l=0;l<64;++l)a[g][t][l]=ad(gen);for(unsigned w=0;w<5;++w){m89_axis128_t i;i.data=0;if(w<4)for(unsigned b=0;b<16;++b)i.data.range(8*b+7,8*b)=ap_uint<8>(a[g][t][16*w+b]);else i.data.range(15,0)=hb(as[g][t]);i.keep=-1;i.strb=-1;i.last=g+1==G&&t==31&&w==4;tx.write(i);}}
 for(unsigned s=0;s<S;++s)for(unsigned g=0;g<G;++g){unsigned base=g*W;ap_uint<128>tag=0;bool o[8];half ws[8];for(unsigned r=0;r<8;++r){o[r]=bd(gen);ws[r]=(half)(0.003f*(1+s+g+r));tag.range(16*r+15,16*r)=hb(ws[r])|((ap_uint<16>)o[r]<<15);}m[s][base]=tag;for(unsigned p=0;p<4;++p){ap_uint<128>l0=0,h0=0,l1=0,h1=0;int d[32][2]={};for(unsigned l=0;l<64;++l){int c0=cd(gen),c1=cd(gen);put(l0,h0,l,bits,c0);put(l1,h1,l,bits,c1);for(unsigned t=0;t<32;++t){d[t][0]+=a[g][t][l]*(qm(bits,o[2*p])+c0);d[t][1]+=a[g][t][l]*(qm(bits,o[2*p+1])+c1);}}for(unsigned t=0;t<32;++t){half v0=(half)((half)d[t][0]*as[g][t])*ws[2*p],v1=(half)((half)d[t][1]*as[g][t])*ws[2*p+1];gold[t][s][2*p]=(half)(gold[t][s][2*p]+v0);gold[t][s][2*p+1]=(half)(gold[t][s][2*p+1]+v1);}unsigned at=base+1+p*bits;m[s][at]=l0;if(bits==4)m[s][at+1]=h0;m[s][at+bits/2]=l1;if(bits==4)m[s][at+bits/2+1]=h1;}}
 ap_uint<32>st,bu,ca,ma;m89s_scaleaware(tx,m[0],m[1],m[2],m[3],rx,G,R,bits,st,bu,ca,ma);if(st||bu!=0x4D383953U||ca!=1||ma!=G*R*S*32)return 1;for(unsigned t=0;t<32;++t)for(unsigned s=0;s<S;++s)for(unsigned p=0;p<4;++p){m89_axis64_t i=rx.read();if(i.data.range(15,0)!=hb(gold[t][s][2*p])||i.data.range(47,32)!=hb(gold[t][s][2*p+1])){std::cerr<<"mismatch bits="<<bits<<" t="<<t<<" s="<<s<<" p="<<p<<"\n";return 2;}}return rx.empty()?0:3;}
int main(){if(run(2)||run(4))return 1;std::cout<<"M89S_SCALEAWARE_T32_W2W4_FP16_ACCUM_CSIM_PASS\n";return 0;}
